def check_n(n):
    if n == 3:
        # Solution: a1=0, a2=1, a3=2
        a = [0, 1, 2]
        sums = set()
        for i in range(n):
            for j in range(i + 1, n):
                sums.add(a[i] + a[j])
        expected_max = n * (n - 1) // 2
        expected_sums = set(range(1, expected_max + 1))

        print(f"N={n}: Found sums: {sorted(list(sums))}. Expected sums: {sorted(list(expected_sums))}")
        if sums == expected_sums:
            return True
        return False

    elif n == 4:
        # Solution: a1=0, a2=1, a3=2, a4=4
        a = [0, 1, 2, 4]
        sums = set()
        for i in range(n):
            for j in range(i + 1, n):
                sums.add(a[i] + a[j])
        expected_max = n * (n - 1) // 2
        expected_sums = set(range(1, expected_max + 1))

        print(f"N={n}: Found sums: {sorted(list(sums))}. Expected sums: {sorted(list(expected_sums))}")
        if sums == expected_sums:
            return True
        return False
    return False

print(f"N=3 works: {check_n(3)}")
print(f"N=4 works: {check_n(4)}")

